def transform_v2(grid):
    """For each row with >= 2 non-zeros, fill between them"""
    result = []
    for r in range(len(grid)):
        row = list(grid[r])
        non_zeros = [(c, grid[r][c]) for c in range(len(row)) if grid[r][c] != 0]

        if len(non_zeros) >= 2:
            min_col, max_col = min(c for c,_ in non_zeros), max(c for c,_ in non_zeros)
            for c in range(min_col, max_col + 1):
                if row[c] == 0:
                    row[c] = 2

        result.append(row)
    return result

